public class Trie {
    private static class Node {
        boolean end = false;
        Node[] children = new Node[26];
    }
    private final Node root = new Node();
    public void insert(String w) {
        Node cur = root;
        for (char c : w.toCharArray()) {
            int i = c - 'a';
            if (cur.children[i] == null) cur.children[i] = new Node();
            cur = cur.children[i];
        }
        cur.end = true;
    }
    public boolean search(String w) {
        Node n = find(w);
        return n != null && n.end;
    }
    public boolean startsWith(String p) { return find(p) != null; }
    private Node find(String s) {
        Node cur = root;
        for (char c : s.toCharArray()) {
            int i = c - 'a';
            if (cur.children[i] == null) return null;
            cur = cur.children[i];
        }
        return cur;
    }
    public static void main(String[] args) {
        Trie t = new Trie();
        t.insert("apple");
        System.out.println(t.search("apple"));
        System.out.println(t.startsWith("app"));
        System.out.println(t.search("app"));
    }
}

public class Main {
    static class ListNode { int val; ListNode next; ListNode(int v){ val = v; } }
    static class MyLinkedList {
        private ListNode head; private int size;
        public void addAtHead(int v){ ListNode n = new ListNode(v); n.next = head; head = n; size++; }
        public int get(int i){
            if (i < 0 || i >= size) return -1;
            ListNode c = head; for (int k=0;k<i;k++) c = c.next; return c.val;
        }
        public void addAtTail(int v){ if (head==null){addAtHead(v);return;} ListNode c=head; while(c.next!=null)c=c.next; c.next=new ListNode(v); size++; }
        public void addAtIndex(int i,int v){
            if (i>size) return; if (i==0){addAtHead(v);return;} if (i==size){addAtTail(v);return;}
            ListNode c=head; for(int k=0;k<i-1;k++)c=c.next;
            ListNode n=new ListNode(v); n.next=c.next; c.next=n; size++;
        }
        public void deleteAtIndex(int i){
            if (i<0||i>=size) return;
            if (i==0){head=head.next; size--; return;}
            ListNode c=head; for(int k=0;k<i-1;k++)c=c.next;
            c.next=c.next.next; size--;
        }
    }
    public static void main(String[] args){
        MyLinkedList l=new MyLinkedList();
        l.addAtHead(1); l.addAtTail(3); l.addAtIndex(1,2);
        System.out.println(l.get(1)); System.out.println(l.get(0)); System.out.println(l.get(2));
    }
}
